text = P.read_text(encoding='utf-8')
applied = skipped = 0
for old, new in REPLS:
    if old not in text:
        skipped += 1
        continue
    text = text.replace(old, new, 1)
    applied += 1
P.write_text(text, encoding='utf-8')
print(f'Pipeline template: applied={applied}, skipped={skipped}')
